insert into public.tips (section, min_age_months, max_age_months, title_ar, title_en, body_ar, body_en, source, sort_order, status) values
  ('sleep', 0, 2, 'النوم الآمن', 'Safe sleep', 'ضع الرضيع على ظهره للنوم، على سطح ثابت ومسطح، بدون وسائد أو ألعاب أو أغطية رخوة. ينام حديثو الولادة عادة ١٤–١٧ ساعة يومياً على فترات قصيرة.', 'Put your baby to sleep on their back, on a firm flat surface, with no pillows, toys or loose blankets. Newborns usually sleep 14–17 hours a day in short stretches.', 'General guidance (WHO / AAP); pending paediatrician review', 1, 'published'),
  ('feeding', 0, 2, 'الرضاعة عند الطلب', 'Feed on demand', 'يرضع المولود عادة كل ٢–٣ ساعات. الرضاعة الطبيعية وحدها تكفي في الأشهر الستة الأولى، ولا يحتاج الرضيع إلى الماء. استشر الطبيب في أي سؤال عن الحليب الصناعي.', 'Newborns usually feed every 2–3 hours. Breast milk alone is enough for the first six months, and babies don''t need water. Ask your doctor about any formula questions.', 'General guidance (WHO / AAP); pending paediatrician review', 2, 'published'),
  ('activities', 0, 2, 'وقت البطن', 'Tummy time', 'ضع طفلك على بطنه وهو مستيقظ وتحت نظرك لبضع دقائق عدة مرات يومياً. هذا يقوي الرقبة والكتفين.', 'Put your baby on their tummy while awake and watched, for a few minutes several times a day. It builds neck and shoulder strength.', 'General guidance (WHO / AAP); pending paediatrician review', 3, 'published'),
  ('learning', 0, 2, 'تحدث وغنِّ', 'Talk and sing', 'تحدث مع طفلك وغنِّ له وانظر في عينيه. يتعلم الرضيع اللغة من صوتك حتى قبل أن يتكلم، بالعربية أو بأي لغة تتحدثون بها في البيت.', 'Talk, sing and make eye contact with your baby. Babies learn language from your voice long before they speak, in Arabic or any language you use at home.', 'General guidance (WHO / AAP); pending paediatrician review', 4, 'published'),
  ('health', 0, 2, 'متى تتصل بالطبيب', 'When to call the doctor', 'الحرارة ٣٨ درجة أو أكثر لرضيع عمره أقل من ٣ أشهر تحتاج إلى طبيب فوراً. وكذلك صعوبة التنفس، أو رفض الرضاعة، أو الخمول الشديد.', 'A temperature of 38°C or more in a baby under 3 months needs a doctor straight away. So do trouble breathing, refusing feeds, or being very floppy or sleepy.', 'General guidance (WHO / AAP); pending paediatrician review', 5, 'published'),
  ('sleep', 3, 5, 'روتين قبل النوم', 'A bedtime routine', 'ابدأ روتيناً بسيطاً كل ليلة: حمام دافئ، ثم رضعة، ثم أغنية هادئة. يحتاج الرضيع عادة ١٢–١٦ ساعة نوم يومياً مع القيلولة.', 'Start a simple routine each night: a warm bath, a feed, then a quiet song. Babies this age usually need 12–16 hours of sleep a day including naps.', 'General guidance (WHO / AAP); pending paediatrician review', 6, 'published'),
  ('feeding', 3, 5, 'لا طعام صلب بعد', 'Not solids yet', 'معظم الرضع لا يحتاجون طعاماً صلباً قبل حوالي ٦ أشهر. علامات الاستعداد: الجلوس بدعم، والتحكم بالرأس، والاهتمام بالطعام.', 'Most babies don''t need solid food before about 6 months. Signs of readiness: sitting with support, good head control, and interest in food.', 'General guidance (WHO / AAP); pending paediatrician review', 7, 'published'),
  ('activities', 3, 5, 'الوصول والإمساك', 'Reach and grab', 'قدم ألعاباً آمنة وملونة على مسافة قريبة ليمد يده إليها. ألعاب الخشخيشة والكتب القماشية مناسبة جداً.', 'Hold safe, colourful toys just within reach so your baby stretches for them. Rattles and cloth books are great.', 'General guidance (WHO / AAP); pending paediatrician review', 8, 'published'),
  ('learning', 3, 5, 'ردّ على أصواته', 'Answer their sounds', 'عندما يناغي طفلك، ردّ عليه وانتظر دوره ليرد. هذه أول محادثة بينكما.', 'When your baby babbles, answer and wait for their "reply". This is your first conversation together.', 'General guidance (WHO / AAP); pending paediatrician review', 9, 'published'),
  ('health', 3, 5, 'التطعيمات في موعدها', 'Vaccines on time', 'تطعيمات الشهر الرابع مهمة. افتح جدول التطعيمات في التطبيق لترى الموعد القادم.', 'The 4-month vaccines are important. Open the vaccination schedule in the app to see the next date.', 'General guidance (WHO / AAP); pending paediatrician review', 10, 'published'),
  ('sleep', 6, 11, 'قيلولتان في اليوم', 'Two naps a day', 'يأخذ كثير من الأطفال في هذا العمر قيلولتين يومياً. حافظ على موعد ثابت للنوم ليلاً.', 'Many babies this age take two naps a day. Keep a regular bedtime at night.', 'General guidance (WHO / AAP); pending paediatrician review', 11, 'published'),
  ('feeding', 6, 11, 'بداية الطعام الصلب', 'Starting solids', 'ابدأ حوالي ٦ أشهر بأطعمة مهروسة أو طرية: خضار، فواكه، حبوب مدعمة بالحديد. لا عسل قبل عمر سنة، ولا قطع صلبة صغيرة يمكن أن تسبب الاختناق.', 'Around 6 months, start soft or mashed foods: vegetables, fruit, iron-fortified cereal. No honey before age one, and no small hard pieces that could cause choking.', 'General guidance (WHO / AAP); pending paediatrician review', 12, 'published'),
  ('activities', 6, 11, 'الحبو والاستكشاف', 'Crawling and exploring', 'وفّر مساحة آمنة على الأرض ليتحرك ويحبو. أغلق المقابس وثبّت الأثاث وأبعد الأشياء الصغيرة.', 'Give your baby safe floor space to move and crawl. Cover sockets, anchor furniture and keep small objects out of reach.', 'General guidance (WHO / AAP); pending paediatrician review', 13, 'published'),
  ('learning', 6, 11, 'أسماء الأشياء', 'Name things', 'سمِّ الأشياء التي ينظر إليها طفلك: "هذه كرة"، "هذا ماء". الكتب ذات الصور الكبيرة رائعة.', 'Name what your baby looks at: "That''s a ball", "This is water". Picture books with big images are great.', 'General guidance (WHO / AAP); pending paediatrician review', 14, 'published'),
  ('health', 6, 11, 'الأسنان الأولى', 'First teeth', 'نظّف السن الأول بفرشاة ناعمة وكمية صغيرة جداً من معجون الأطفال بالفلورايد. العضّاضة الباردة تساعد عند التسنين.', 'Clean the first tooth with a soft brush and a tiny smear of fluoride toothpaste. A cool teether helps with teething.', 'General guidance (WHO / AAP); pending paediatrician review', 15, 'published'),
  ('sleep', 12, 23, '١١–١٤ ساعة نوم', '11–14 hours of sleep', 'يحتاج الطفل في السنة الثانية عادة ١١–١٤ ساعة نوم يومياً مع قيلولة أو اثنتين. أبعد الشاشات قبل النوم.', 'Toddlers usually need 11–14 hours of sleep a day with one or two naps. Keep screens away before bed.', 'General guidance (WHO / AAP); pending paediatrician review', 16, 'published'),
  ('feeding', 12, 23, 'طعام العائلة', 'Family food', 'يستطيع طفلك أن يأكل معظم طعام العائلة مقطعاً قطعاً صغيرة وطرية، مع تقليل الملح والسكر. شجعه على استخدام الملعقة والكوب.', 'Your toddler can eat most family food cut small and soft, with little salt and sugar. Encourage a spoon and an open cup.', 'General guidance (WHO / AAP); pending paediatrician review', 17, 'published'),
  ('activities', 12, 23, 'المشي واللعب في الداخل', 'Walking and indoor play', 'في صيف الكويت، العب في الداخل أو في الصباح الباكر والمساء. ألعاب الدفع والمكعبات تقوي التوازن.', 'In Kuwait''s summer, play indoors or early morning and evening. Push toys and blocks help balance.', 'General guidance (WHO / AAP); pending paediatrician review', 18, 'published'),
  ('learning', 12, 23, 'لا شاشات تقريباً', 'Almost no screens', 'تنصح الجهات الصحية بتجنب الشاشات تحت عمر ١٨–٢٤ شهراً إلا مكالمات الفيديو مع العائلة. اقرأ قصة بدلاً منها.', 'Health bodies advise avoiding screens under 18–24 months, except video calls with family. Read a story instead.', 'General guidance (WHO / AAP); pending paediatrician review', 19, 'published'),
  ('health', 12, 23, 'السلامة في البيت', 'Safety at home', 'أغلق أدوية المنزل والمنظفات بعيداً عن متناوله، وراقبه دائماً قرب الماء، حتى في حوض الاستحمام.', 'Lock away medicines and cleaning products, and always watch your child near water, even in the bath.', 'General guidance (WHO / AAP); pending paediatrician review', 20, 'published'),
  ('sleep', 24, 35, 'روتين ثابت', 'A steady routine', 'روتين ثابت (حمام، أسنان، قصة) يسهّل النوم. ينام الطفل في هذا العمر عادة ١١–١٤ ساعة مع القيلولة.', 'A steady routine (bath, teeth, story) makes bedtime easier. Children this age usually sleep 11–14 hours including a nap.', 'General guidance (WHO / AAP); pending paediatrician review', 21, 'published'),
  ('feeding', 24, 35, 'تنوع في الطبق', 'Variety on the plate', 'قدّم خضاراً وفاكهة وبروتيناً وحبوباً كاملة كل يوم. من الطبيعي أن يرفض طعاماً جديداً، فكرر تقديمه بهدوء.', 'Offer vegetables, fruit, protein and whole grains every day. It''s normal to refuse new foods: offer them again, calmly.', 'General guidance (WHO / AAP); pending paediatrician review', 22, 'published'),
  ('activities', 24, 35, 'ساعة لعب حر', 'Free play', 'يحتاج الطفل للعب نشط كل يوم: الركض، القفز، الرمي. الحدائق المظللة والمراكز الداخلية خيار جيد في الحر.', 'Children need active play every day: running, jumping, throwing. Shaded parks and indoor play centres are good options in the heat.', 'General guidance (WHO / AAP); pending paediatrician review', 23, 'published'),
  ('learning', 24, 35, 'كلمات جديدة كل يوم', 'New words every day', 'اقرأ معه يومياً واطلب منه أن يشير إلى الصور. حتى ساعة واحدة يومياً من الشاشات تكفي في هذا العمر، ويفضل أن تكون مع أحد الوالدين.', 'Read together daily and ask your child to point to pictures. Keep screens to about one hour a day at most, ideally with a parent.', 'General guidance (WHO / AAP); pending paediatrician review', 24, 'published'),
  ('health', 24, 35, 'التدريب على الحمام', 'Potty training', 'يبدأ كثير من الأطفال بين سنتين وثلاث سنوات. علامات الاستعداد: البقاء جافاً لساعتين، والإحساس بالحاجة. كن صبوراً ولا تعاقب.', 'Many children start between 2 and 3 years. Signs of readiness: staying dry for 2 hours and noticing the need to go. Be patient and never punish.', 'General guidance (WHO / AAP); pending paediatrician review', 25, 'published'),
  ('sleep', 36, 59, '١٠–١٣ ساعة', '10–13 hours', 'يحتاج الطفل من ٣ إلى ٥ سنوات عادة ١٠–١٣ ساعة نوم، وقد يتوقف عن القيلولة. موعد نوم ثابت مهم حتى في الإجازات.', 'Children aged 3–5 usually need 10–13 hours of sleep and may drop the nap. A steady bedtime matters, even on holidays.', 'General guidance (WHO / AAP); pending paediatrician review', 26, 'published'),
  ('feeding', 36, 59, 'وجبات خفيفة صحية', 'Healthy snacks', 'قدّم الفاكهة والخضار المقطعة واللبن بدلاً من الحلويات والعصائر المحلاة. الماء هو أفضل مشروب.', 'Offer cut fruit, vegetables and yoghurt instead of sweets and sweetened juice. Water is the best drink.', 'General guidance (WHO / AAP); pending paediatrician review', 27, 'published'),
  ('activities', 36, 59, '٣ ساعات حركة', 'Three hours of movement', 'توصي منظمة الصحة العالمية بثلاث ساعات من النشاط الحركي يومياً لهذا العمر، موزعة على اليوم. السباحة والدراجة وألعاب الكرة ممتازة.', 'WHO recommends three hours of physical activity a day at this age, spread through the day. Swimming, bikes and ball games are great.', 'General guidance (WHO / AAP); pending paediatrician review', 28, 'published'),
  ('learning', 36, 59, 'استعداد للروضة', 'Getting ready for kindergarten', 'تدرّب على الحروف والأرقام بالألعاب، وشجعه على اللعب مع أطفال آخرين وانتظار دوره.', 'Practise letters and numbers through games, and encourage playing with other children and taking turns.', 'General guidance (WHO / AAP); pending paediatrician review', 29, 'published'),
  ('health', 36, 59, 'حماية من الحر', 'Protect from the heat', 'في الصيف، تجنب اللعب في الخارج من الظهر حتى العصر، وقدّم الماء كثيراً، واستخدم القبعة وواقي الشمس.', 'In summer, avoid outdoor play from noon to late afternoon, offer water often, and use a hat and sunscreen.', 'General guidance (WHO / AAP); pending paediatrician review', 30, 'published'),
  ('sleep', 60, 83, '٩–١٢ ساعة', '9–12 hours', 'يحتاج طفل المدرسة عادة ٩–١٢ ساعة نوم. أبعد الأجهزة عن غرفة النوم لنوم أفضل.', 'School-age children usually need 9–12 hours of sleep. Keep devices out of the bedroom for better sleep.', 'General guidance (WHO / AAP); pending paediatrician review', 31, 'published'),
  ('feeding', 60, 83, 'فطور قبل المدرسة', 'Breakfast before school', 'الفطور يساعد على التركيز. جرّب البيض أو الشوفان أو الخبز الأسمر مع الفاكهة، وضع الماء في حقيبته.', 'Breakfast helps concentration. Try eggs, oats or wholemeal bread with fruit, and pack a water bottle.', 'General guidance (WHO / AAP); pending paediatrician review', 32, 'published'),
  ('activities', 60, 83, 'ساعة نشاط يومياً', 'An hour of activity a day', 'يحتاج الطفل من ٥ سنوات فما فوق ٦٠ دقيقة على الأقل من النشاط يومياً. اختر رياضة يحبها: سباحة، كرة، فنون قتالية.', 'Children 5 and older need at least 60 minutes of activity a day. Choose a sport they enjoy: swimming, football, martial arts.', 'General guidance (WHO / AAP); pending paediatrician review', 33, 'published'),
  ('learning', 60, 83, 'القراءة كل ليلة', 'Reading every night', 'عشر دقائق قراءة يومياً بالعربية والإنجليزية تصنع فرقاً كبيراً. دعه يختار الكتب بنفسه.', 'Ten minutes of reading every day, in Arabic and English, makes a big difference. Let your child choose the books.', 'General guidance (WHO / AAP); pending paediatrician review', 34, 'published'),
  ('health', 60, 83, 'فحص النظر والأسنان', 'Eyes and teeth check-ups', 'زيارة طبيب الأسنان كل ستة أشهر، وفحص النظر قبل المدرسة أو إذا لاحظت أنه يقترب كثيراً من الكتب أو الشاشات.', 'See the dentist every six months, and have eyesight checked before school or if your child holds books or screens very close.', 'General guidance (WHO / AAP); pending paediatrician review', 35, 'published'),
  ('sleep', 84, 131, 'النوم والواجبات', 'Sleep and homework', 'حافظ على ٩–١٢ ساعة نوم حتى في أيام الامتحانات. النوم الجيد يحسّن الذاكرة أكثر من السهر.', 'Keep 9–12 hours of sleep even during exams. Good sleep helps memory more than staying up late.', 'General guidance (WHO / AAP); pending paediatrician review', 36, 'published'),
  ('feeding', 84, 131, 'قلّل المشروبات الغازية', 'Cut down on fizzy drinks', 'المشروبات الغازية ومشروبات الطاقة غير مناسبة للأطفال. اجعل الماء والحليب المشروبين الأساسيين.', 'Fizzy and energy drinks aren''t suitable for children. Make water and milk the main drinks.', 'General guidance (WHO / AAP); pending paediatrician review', 37, 'published'),
  ('activities', 84, 131, 'أنشطة جماعية', 'Team activities', 'الرياضات الجماعية والأندية تبني الثقة والصداقات. ابحث في دليل التطبيق عن أنشطة قريبة منك.', 'Team sports and clubs build confidence and friendships. Look in the app''s directory for activities near you.', 'General guidance (WHO / AAP); pending paediatrician review', 38, 'published'),
  ('learning', 84, 131, 'وقت الشاشات بقواعد', 'Screen time with rules', 'اتفقوا معاً على قواعد واضحة لوقت الشاشات والألعاب، وأبعدوا الأجهزة عن وقت الطعام والنوم.', 'Agree clear rules together for screen and gaming time, and keep devices away from meals and bedtime.', 'General guidance (WHO / AAP); pending paediatrician review', 39, 'published'),
  ('health', 84, 131, 'الحديث عن المشاعر', 'Talking about feelings', 'خصص وقتاً يومياً للحديث معه عن يومه ومشاعره. إذا لاحظت حزناً مستمراً أو تغيراً كبيراً في سلوكه، تحدث مع طبيبه.', 'Make time each day to talk about their day and feelings. If you notice lasting sadness or a big change in behaviour, talk to their doctor.', 'General guidance (WHO / AAP); pending paediatrician review', 40, 'published');
